if(B.b.m(a,"\ub85c\uadf8"))return"\ubcc0\ud615 \uc608\uc81c: log\u20839=2\ub294 3\xb2=9\ub97c \ub85c\uadf8 \uae30\ud638\ub85c \ub2e4\uc2dc \uc4f4 \uac83\uc774\ub2e4. \uac19\uc740 \uc218\ub77c\ub3c4 \ubc11\uc774 \ub2ec\ub77c\uc9c0\uba74 \uac12\uc774 \ub2ec\ub77c\uc9c4\ub2e4."
